def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_last, opp_last = history[-1]

    opp_c = 0
    for a, b in history:
        if b == 'C':
            opp_c += 1
    opp_d = n - opp_c
    opp_rate = opp_c / float(n)

    r5 = history[-5:]
    r10 = history[-10:]

    opp_d5 = 0
    opp_c5 = 0
    for a, b in r5:
        if b == 'C':
            opp_c5 += 1
        else:
            opp_d5 += 1

    opp_d10 = 0
    opp_c10 = 0
    for a, b in r10:
        if b == 'C':
            opp_c10 += 1
        else:
            opp_d10 += 1

    mirror_num = 0
    after_d_c = 0
    after_d_d = 0
    for i in range(1, n):
        prev_a = history[i - 1][0]
        opp_now = history[i][1]
        if prev_a == opp_now:
            mirror_num += 1
        if prev_a == 'D':
            if opp_now == 'C':
                after_d_c += 1
            else:
                after_d_d += 1

    mirror = mirror_num / float(n - 1) if n > 1 else 1.0
    nonretal = after_d_c >= 1 and after_d_d == 0

    mutual_streak = 0
    for a, b in reversed(history):
        if a == 'D' and b == 'D':
            mutual_streak += 1
        else:
            break

    if n == 99:
        return 'D'

    if n >= 3:
        if my_last == 'C' and opp_last == 'D':
            p2 = history[-2]
            if p2[0] == 'D' and p2[1] == 'C':
                if opp_d10 < 8 and (mirror >= 0.5 or after_d_d >= 1):
                    return 'C'

    if n <= 8:
        if mutual_streak >= 2:
            return 'C'
        if my_last == 'C' and opp_last == 'C':
            return 'C'
        if n >= 2:
            p2 = history[-2]
            if my_last == 'C' and opp_last == 'D' and p2[0] == 'D':
                return 'C'

    if n == 98:
        if opp_last == 'D':
            return 'D'
        if opp_d == 0 or nonretal:
            return 'D'

    if opp_rate <= 0.30 or opp_d10 >= 8:
        return 'D'

    if opp_d5 >= 5 and opp_last == 'D':
        return 'D'

    if nonretal and opp_rate >= 0.60:
        return 'D'

    if (
        mutual_streak >= 2
        and opp_c5 >= 1
        and opp_c >= max(4, n // 5)
        and mirror >= 0.5
    ):
        return 'C'

    if opp_c5 >= 4:
        return 'C'
    if opp_c10 >= 9:
        return 'C'
    if opp_rate >= 0.80:
        return 'C'
    if opp_rate <= 0.30:
        return 'D'

    if my_last == 'C' and opp_last == 'D':
        return 'D'
    if my_last == 'D' and opp_last == 'C':
        return 'C'

    if n >= 20:
        last20 = history[-20:]
        d_after_d = 0
        for i in range(1, len(last20)):
            if last20[i - 1][1] == 'D' and last20[i][1] == 'D':
                d_after_d += 1
        if d_after_d >= 5:
            return 'D'

    if opp_rate >= 0.45:
        return 'C'
    return 'D'
